-- ============================================================
-- DOPAZON — fix product images  (Supabase SQL Editor -> Run)
--
-- Why: the seeder assigned real Unsplash photos using a GLOBAL
-- counter instead of a per-category one, so only the first ~12
-- products ever got one. The other ~988 fell back to
-- picsum.photos placeholders, which now return 503 and are also
-- blocked by the site's Content-Security-Policy. Net effect:
-- almost every product rendered with no image at all.
--
-- This assigns every seeded product a verified, category-
-- appropriate photo, cycling through the pool per category.
-- Products created by real users (user_id IS NOT NULL) are left
-- untouched. Safe to re-run.
-- ============================================================

WITH pools(category, urls) AS (VALUES
  ('art', ARRAY['https://images.unsplash.com/photo-1513364776144-60967b0f800f?w=400&q=80','https://images.unsplash.com/photo-1460661419201-fd4cecdf8a8b?w=400&q=80','https://images.unsplash.com/photo-1452860606245-08befc0ff44b?w=400&q=80','https://images.unsplash.com/photo-1547891654-e66ed7ebb968?w=400&q=80','https://images.unsplash.com/photo-1579762715118-a6f1d4b934f1?w=400&q=80','https://images.unsplash.com/photo-1541961017774-22349e4a1262?w=400&q=80','https://images.unsplash.com/photo-1499892477393-f675706cbe6e?w=400&q=80','https://images.unsplash.com/photo-1578321272176-b7bbc0679853?w=400&q=80','https://images.unsplash.com/photo-1568205612837-017257d2310a?w=400&q=80']),
