),
ranked AS (
  SELECT id, category,
         row_number() OVER (PARTITION BY category ORDER BY created_at, id) - 1 AS rn
  FROM products
  WHERE user_id IS NULL
)
UPDATE products p
SET img = pools.urls[(ranked.rn % array_length(pools.urls, 1)) + 1]
FROM ranked, pools
WHERE p.id = ranked.id
  AND pools.category = ranked.category;

-- Any seeded product in a category with no pool (shouldn't happen)
-- keeps whatever it had; verify nothing is left on picsum:
--   SELECT count(*) FROM products WHERE img LIKE '%picsum%';
